import{_ as a}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{C as i,c as n,o,ag as t,G as r}from"./chunks/mermaid.Bf0DxEx6.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const v=JSON.parse('{"title":"Tailscale getting-started tutorial","description":"Tailscale lets devices signed in to the same account reach each other as if they were on the same LAN, with traffic encrypted end to end and no public IP address or port forwarding needed. This page walks you through connecting two devices, confirming they can reach each other, getting in with Tailscale SSH, and then working through six everyday development scenarios.","frontmatter":{"title":"Tailscale getting-started tutorial","description":"Tailscale lets devices signed in to the same account reach each other as if they were on the same LAN, with traffic encrypted end to end and no public IP address or port forwarding needed. This page walks you through connecting two devices, confirming they can reach each other, getting in with Tailscale SSH, and then working through six everyday development scenarios.","domain":"product","tags":["mesh-vpn","remote-access","wireguard","tailscale"],"role":"tutorial","pageClass":"wide-figures"},"headers":[],"relativePath":"products/tailscale/tailscale.md","filePath":"products/tailscale/tailscale.md","lastUpdated":1795792629000}'),l={name:"products/tailscale/tailscale.md"};function h(d,e,c,p,u,g){const s=i("DocDiagram");return o(),n("div",null,[e[0]||(e[0]=t("",29)),r(s,{src:"/diagrams/tailscale-connection.en.svg",alt:"This sequence diagram has five vertical lanes. From left to right: device A, device B, the identity provider, the coordination server (the control plane), and the DERP relay server, which also acts as a STUN server. Numbers give the order. Step 1: device A and device B each log in to the identity provider; Tailscale itself does no user authentication. Step 2: each device sends the coordination server a MapRequest containing its own node public key, addresses and candidate endpoints. Step 3: the coordination server sends the network map, or netmap, to device A and device B. It tells each device whether the other exists, the other node's public key, its Tailscale address, its candidate endpoints and its home DERP region, and it includes only the nodes the policy allows that device to see. Step 4: device A connects to the DERP server that device B uses, DERP passes the connection request to device B, and then the two sides exchange the endpoint information needed for a direct connection through DERP; paths through DERP are drawn as amber dashed lines. Step 5: both sides first use STUN to discover their own public address, then try each candidate endpoint to traverse NAT. If that succeeds they establish a direct WireGuard UDP tunnel, drawn as a thick green line, and after that the data passes through no third party. Step 6: if the direct path fails, Tailscale first tries a Peer Relay inside the tailnet, drawn as a cyan dashed line; a Peer Relay requires explicit setup and is not there by default. Only when no Peer Relay is available does it keep using the DERP relay to forward already-encrypted WireGuard packets, drawn as an amber dashed line. Step 7: Tailscale on the devices retries periodically to see whether the connection can upgrade to direct or to a Peer Relay. Step 8 is two protection notes: the coordination server only distributes public keys and policy, is not on the data path and never sees plaintext; DERP only forwards already-encrypted WireGuard packets and cannot decrypt them. The difference between direct and fallback: with a direct connection the data travels only between the two devices and no third party is involved; with a fallback the data is relayed, and when it is relayed through DERP what DERP forwards is still encrypted WireGuard packets. Orange solid lines are control and negotiation messages. This diagram omits: a separate lane for the Peer Relay; the internal steps of the WireGuard handshake and key negotiation; NAT types and the details of hole punching; the interval between periodic retries; the number and location of DERP regions; the contents of the policy the coordination server distributes.",width:1020,lang:"en"}),e[1]||(e[1]=t("",133))])}const b=a(l,[["render",h]]);export{v as __pageData,b as default};
